const DICTATION_PREFIXES = [
  'type', 'write', 'reply', 'dictate',
  'लिखो', 'लिख', 'टाइप करो', 'जवाब दो', 'उत्तर दो',
  'likho', 'jawab do',
];

/** Dictation, matched by an explicit imperative prefix, before the length gate. */
function matchDictation(transcript) {
  const raw = transcript.trim();
  const lower = raw.toLowerCase();
  for (const prefix of DICTATION_PREFIXES) {
    if (!lower.startsWith(prefix)) continue;
    const rest = raw.slice(prefix.length);
    if (rest && !/^[\s:,-]/.test(rest)) continue;
    const text = rest.replace(/^[\s:,-]+/, '').trim();
    if (text) return { text };
  }
  return null;
}

/** Strip punctuation and collapse whitespace, preserving Devanagari. */
export function normalise(input) {
  return input
    .toLowerCase()
    .replace(/[.,!?;:'"“”‘’()\[\]{}]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/** Whether the whole utterance IS this command. Equality after filler is
 *  removed: containment fired on any short sentence carrying an ordinary word
 *  like "light" or "down". */
function isPhrase(text, phrase) {
  if (text === phrase) return true;
  return text.split(' ').filter(w => !FILLER.has(w)).join(' ') === phrase;
}

export function matchLocalIntent(transcript, locale = '') {
  const dictated = matchDictation(transcript);
  if (dictated) {
    return { transcript, locale, intent: 'dictate', args: { text: dictated.text }, reply: 'Ready to send' };
  }

  const text = normalise(transcript);
  if (!text) return null;
  if (text.split(' ').length > MAX_WORDS) return null;

  // Longest phrase first, so "scroll down" beats "down".
  let best = null;
  for (const rule of RULES) {
    for (const phrase of rule.any) {
      if (!isPhrase(text, phrase)) continue;
      if (!best || phrase.length > best.length) best = { rule, length: phrase.length };
    }
  }
  if (best) {
    return {
      transcript,
      locale,
      intent: best.rule.intent,
      args: best.rule.args ?? {},
      reply: best.rule.reply,
    };
  }

  // Every remaining destination, matched by equality after filler exactly as
  // above — never containment, because the table holds ordinary words.
  const stripped = text.split(' ').filter(w => !FILLER.has(w)).join(' ');
  const key = DESTINATIONS[text] ? text : DESTINATIONS[stripped] ? stripped : null;
  if (key) {
    return { transcript, locale, intent: 'navigate', args: { destination: key }, reply: routeLabel(DESTINATIONS[key]) };
  }

  return null;
}

function routeLabel(route) {
  const slug = route.replace(/^.*\//, '').replace(/[()]/g, '');
  const words = slug.replace(/-/g, ' ').trim();
  return words ? words.charAt(0).toUpperCase() + words.slice(1) : 'Done';
}
